UPDATE public.preguntas SET pregunta_en = 'What is the difference between perfect and imperfect contrition (attrition)?', opcion_a_en = 'There is no theological difference', opcion_b_en = 'Perfect contrition arises from love of God; imperfect contrition, from fear of punishment', opcion_c_en = 'Imperfect contrition is invalid', opcion_d_en = 'Perfect contrition needs no Confession', pregunta_fr = 'Quelle différence y a-t-il entre la contrition parfaite et imparfaite (attrition) ?', opcion_a_fr = 'Il n''y a pas de différence théologique', opcion_b_fr = 'La parfaite naît de l''amour de Dieu ; l''imparfaite, de la crainte des châtiments', opcion_c_fr = 'L''imparfaite est invalide', opcion_d_fr = 'La parfaite ne nécessite pas de Confession', pregunta_de = 'Worin unterscheiden sich vollkommene und unvollkommene Reue (Furchtreue)?', opcion_a_de = 'Es gibt keinen theologischen Unterschied', opcion_b_de = 'Die vollkommene entspringt der Liebe zu Gott, die unvollkommene der Furcht vor Strafen', opcion_c_de = 'Die unvollkommene ist ungültig', opcion_d_de = 'Die vollkommene benötigt keine Beichte', pregunta_pt = 'Qual a diferença entre contrição perfeita e imperfeita (atrição)?', opcion_a_pt = 'Não há diferença teológica', opcion_b_pt = 'A perfeita nasce do amor a Deus; a imperfeita, do medo dos castigos', opcion_c_pt = 'A imperfeita é inválida', opcion_d_pt = 'A perfeita não precisa de Confissão', pregunta_it = 'Che differenza c''è tra contrizione perfetta e imperfetta (attrizione)?', opcion_a_it = 'Non c''è differenza teologica', opcion_b_it = 'La perfetta nasce dall''amore di Dio; l''imperfetta, dal timore delle pene', opcion_c_it = 'L''imperfetta è invalida', opcion_d_it = 'La perfetta non necessita di Confessione' WHERE video_id = (SELECT vd.id FROM public.videos vd JOIN public.sacramentos sc ON sc.id = vd.sacramento_id WHERE sc.slug = 'tc2_confesion' AND vd.orden = 5) AND orden = 2;
