DO $$
DECLARE faltan INT;
BEGIN
  SELECT COUNT(*) INTO faltan FROM public.preguntas WHERE pregunta_en IS NULL OR pregunta_fr IS NULL OR pregunta_de IS NULL OR pregunta_pt IS NULL OR pregunta_it IS NULL;
  IF faltan > 0 THEN
    RAISE EXCEPTION 'Migración de traducciones incompleta: % preguntas sin alguna traducción', faltan;
  END IF;
END $$;

COMMIT;

